<?php require_once __DIR__.'/../config/config.php';
$u=require_role(['teacher']);$uid=$u['id'];$action=$_GET['action']??$_POST['action']??'';$method=$_SERVER['REQUEST_METHOD'];
function own_grade(int $id,int $uid):array{$st=db()->prepare('SELECT g.* FROM grades g JOIN students s ON s.id=g.student_id WHERE g.id=? AND s.teacher_id=?');$st->execute([$id,$uid]);$r=$st->fetch();if(!$r)json_response(['success'=>false,'message'=>'Bài kiểm tra không tồn tại.'],404);return $r;}
if($action==='save'&&$method==='POST'){$id=(int)($_POST['id']??0);$sid=(int)($_POST['student_id']??0);own_student($sid,$uid);$date=$_POST['test_date']??'';$name=trim($_POST['test_name']??'');$score=(float)($_POST['score']??-1);$mistakes=trim($_POST['mistakes']??'');if(!$date||$name===''||$score<0||$score>10)json_response(['success'=>false,'message'=>'Dữ liệu điểm không hợp lệ.'],422);if($id){own_grade($id,$uid);$st=db()->prepare('UPDATE grades SET test_date=?,test_name=?,score=?,mistakes=? WHERE id=?');$st->execute([$date,$name,$score,$mistakes,$id]);}else{$st=db()->prepare('INSERT INTO grades(student_id,test_date,test_name,score,mistakes) VALUES(?,?,?,?,?)');$st->execute([$sid,$date,$name,$score,$mistakes]);$id=(int)db()->lastInsertId();}json_response(['success'=>true,'id'=>$id]);}
if($action==='delete'&&$method==='POST'){$id=(int)($_POST['id']??0);own_grade($id,$uid);db()->prepare('DELETE FROM grades WHERE id=?')->execute([$id]);json_response(['success'=>true]);}
json_response(['success'=>false,'message'=>'Action không hợp lệ'],400);
